package com.andye.warmod.phalanx;import java.util.*;import net.minecraft.world.phys.Vec3;
public final class PhalanxLeadSolver{public record Solution(Vec3 direction,double flightTicks,double elevationDegrees){}private PhalanxLeadSolver(){}public static Optional<Solution> solve(Vec3 muzzle,Vec3 target,Vec3 velocity){Vec3 r=target.subtract(muzzle);double speed=PhalanxConstants.BULLET_SPEED_BLOCKS_PER_TICK,a=velocity.lengthSqr()-speed*speed,b=2*r.dot(velocity),c=r.lengthSqr(),disc=b*b-4*a*c,t;if(Math.abs(a)<1E-9)t=-c/b;else if(disc>=0){double x=(-b-Math.sqrt(disc))/(2*a),y=(-b+Math.sqrt(disc))/(2*a);t=x>0&&y>0?Math.min(x,y):Math.max(x,y);}else return Optional.empty();if(!Double.isFinite(t)||t<=0||t>PhalanxConstants.BULLET_LIFETIME_TICKS)return Optional.empty();Vec3 aim=target.add(velocity.scale(t)).add(0,.5*PhalanxConstants.BULLET_GRAVITY_PER_TICK_SQUARED*t*t,0).subtract(muzzle);if(!aim.isFinite()||aim.lengthSqr()<1E-8)return Optional.empty();Vec3 d=aim.normalize();double e=Math.toDegrees(Math.atan2(d.y,d.horizontalDistance()));return e<PhalanxConstants.MIN_ELEVATION_DEGREES||e>PhalanxConstants.MAX_ELEVATION_DEGREES?Optional.empty():Optional.of(new Solution(d,t,e));}public static Vec3 spread(Vec3 direction,UUID turret,long sequence,long gameTime,double degrees){long seed=turret.getMostSignificantBits()^Long.rotateLeft(turret.getLeastSignificantBits(),17)^sequence*0x9E3779B97F4A7C15L^gameTime^0x5048414C414E58L;SplittableRandom r=new SplittableRandom(seed);Vec3 axis=Math.abs(direction.y)<.9?new Vec3(0,1,0):new Vec3(1,0,0),u=direction.cross(axis).normalize(),v=direction.cross(u).normalize();double radius=Math.tan(Math.toRadians(degrees))*Math.sqrt(r.nextDouble()),angle=r.nextDouble(Math.PI*2);return direction.add(u.scale(Math.cos(angle)*radius)).add(v.scale(Math.sin(angle)*radius)).normalize();}}
